<template><section><header class="page-head"><div><p class="eyebrow">COMMUNITY</p><h2>社区公告</h2></div><el-button v-if="canPublish" type="primary" @click="dialog=true">发布公告</el-button></header><AnnouncementCard v-for="v in items" :key="v.id" :announcement="v" @open="open"/><EmptyState v-if="!items.length"/><el-dialog v-model="dialog" title="发布公告"><el-input v-model="form.title" placeholder="标题"/><el-input v-model="form.content" type="textarea" placeholder="内容"/><el-select v-model="form.category"><el-option label="通知" value="通知"/><el-option label="活动" value="活动"/><el-option label="紧急" value="紧急"/></el-select><el-checkbox v-model="form.top">置顶</el-checkbox><template #footer><el-button type="primary" @click="publish">发布</el-button></template></el-dialog><el-dialog v-model="detailVisible" :title="detail?.title"><p>{{detail?.content}}</p><small>已读 {{detail?.read_count}}</small></el-dialog></section></template><script setup lang="ts">import{ref,onMounted,computed}from'vue';import{ElMessage}from'element-plus';import{listAnnouncements,createAnnouncement,detailAnnouncement}from'../api/announcement';import{authStore}from'../stores/authStore';import type{Announcement}from'../types';import AnnouncementCard from'../components/common/AnnouncementCard.vue';import EmptyState from'../components/common/EmptyState.vue';const items=ref<Announcement[]>([]),dialog=ref(false),detailVisible=ref(false),detail=ref<Announcement>(),form=ref({title:'',content:'',category:'通知',top:false});const canPublish=computed(()=>['staff','admin'].includes(authStore.user?.role||''));async function load(){items.value=await listAnnouncements()}async function open(id:number){detail.value=await detailAnnouncement(id);detailVisible.value=true;load()}async function publish(){try{await createAnnouncement(form.value);dialog.value=false;ElMessage.success('公告已发布');load()}catch(e){ElMessage.error((e as Error).message)}}onMounted(load)</script>
